CREATE OR REPLACE FUNCTION public.get_tester_last_activity(tester_user_ids uuid[]) RETURNS TABLE(user_id uuid, last_activity timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501'; END IF; RETURN QUERY SELECT t.uid, MAX(t.activity_date) FROM (SELECT r.user_id AS uid, r.updated_at AS activity_date FROM public.reptiles r WHERE r.user_id = ANY(tester_user_ids) UNION ALL SELECT f.user_id, f.created_at FROM public.feedings f WHERE f.user_id = ANY(tester_user_ids) UNION ALL SELECT w.user_id, w.created_at FROM public.weight_records w WHERE w.user_id = ANY(tester_user_ids) UNION ALL SELECT h.user_id, h.created_at FROM public.health_records h WHERE h.user_id = ANY(tester_user_ids) UNION ALL SELECT ta.user_id, ta.created_at FROM public.tester_activity ta WHERE ta.user_id = ANY(tester_user_ids)) t GROUP BY t.uid; END $$;
CREATE OR REPLACE FUNCTION public.get_tester_usage_stats(tester_user_ids uuid[]) RETURNS TABLE(user_id uuid, reptiles_count bigint, feedings_count bigint, weights_count bigint, health_count bigint, reproduction_count bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501'; END IF; RETURN QUERY SELECT t.uid, (SELECT COUNT(*) FROM public.reptiles r WHERE r.user_id=t.uid), (SELECT COUNT(*) FROM public.feedings f WHERE f.user_id=t.uid), (SELECT COUNT(*) FROM public.weight_records w WHERE w.user_id=t.uid), (SELECT COUNT(*) FROM public.health_records h WHERE h.user_id=t.uid), (SELECT COUNT(*) FROM public.reproduction_observations ro WHERE ro.user_id=t.uid) FROM unnest(tester_user_ids) AS t(uid); END $$;
REVOKE EXECUTE ON FUNCTION public.get_tester_last_activity(uuid[]), public.get_tester_usage_stats(uuid[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_tester_last_activity(uuid[]), public.get_tester_usage_stats(uuid[]) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.remove_tester_role_on_subscribe(text), public.validate_referral_code(text), public.get_referral_reward_count(uuid), public.generate_referral_code() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.remove_tester_role_on_subscribe(text) TO service_role;
COMMENT ON TABLE public.referral_codes IS 'DEPRECATED: referral program retired; historical records retained only.';
COMMENT ON TABLE public.referral_conversions IS 'DEPRECATED: referral program retired; historical records retained only.';
REVOKE ALL ON TABLE public.referral_codes, public.referral_conversions FROM anon, authenticated;